/**
 * SCRUB GALLERY  (portfolio graphics follow the mouse, bold variant)
 *
 * PURPOSE:
 * All portfolio graphics lie on top of each other. Moving the mouse
 * from left to right over the stage flips through them. On touch
 * screens they change by themselves (and on every tap), unless the
 * visitor prefers reduced motion.
 *
 * HTML: generated by "bold-packages" / "bold-service-example"
 *       in /frontend/build/renderers/bold.js
 */

export function initScrubGallery() {
    const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)").matches;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    for (const stage of document.querySelectorAll("[data-scrub-gallery]")) {
        const images = [...stage.querySelectorAll(".scrub-gallery__image")];
        const title = stage.querySelector("[data-scrub-title]");
        const count = stage.querySelector("[data-scrub-count]");
        const progress = stage.querySelector("[data-scrub-progress]");
        if (images.length < 2) continue;

        let active = 0;
        const total = String(images.length).padStart(2, "0");
        const show = (index) => {
            if (index === active) return;
            images[active].classList.remove("is-active");
            images[index].classList.add("is-active");
            active = index;
            if (title) title.textContent = images[index].dataset.title || "";
            if (count) count.textContent = `${String(index + 1).padStart(2, "0")} / ${total}`;
            if (progress) progress.style.width = `${((index + 1) / images.length) * 100}%`;
        };
        if (progress) progress.style.width = `${100 / images.length}%`;

        if (finePointer) {
            stage.addEventListener("pointermove", (event) => {
                const rect = stage.getBoundingClientRect();
                const share = Math.min(Math.max((event.clientX - rect.left) / rect.width, 0), 0.9999);
                show(Math.floor(share * images.length));
            });
            continue;
        }

        // touch: change on tap (the link opens on a second tap) and by itself
        stage.addEventListener("click", (event) => {
            if (stage.dataset.tapped === String(active)) return;
            event.preventDefault();
            stage.dataset.tapped = String((active + 1) % images.length);
            show((active + 1) % images.length);
        });
        if (!reduced) {
            const timer = setInterval(() => {
                if (!document.body.contains(stage)) return clearInterval(timer);
                const rect = stage.getBoundingClientRect();
                if (rect.bottom > 0 && rect.top < window.innerHeight) show((active + 1) % images.length);
            }, 1800);
        }
    }
}
